class X {
    int i;  // Declared first
    int j;  // Declared second
public:
    X(int val) : j(val), i(j) {}  // Initializer list order differs from declaration order, leading to potential issues
    // Compiler notes: The synthesized constructor will initialize 'i' before 'j', so i(j) uses an uninitialized j.
};

code_example:
#include <iostream>

class X {
    int i;  // Member i declared first
    int j;  // Member j declared second
public:
    X(int val) : j(val), i(j) {  // Initializer list: j first, then i
        std::cout << "Value of i: " << i << std::endl;  // This may print garbage due to uninitialized j
    }
};

int main() {
    X obj(5);  // Calls constructor with val = 5
    return 0;
}
